import "strings"

// Slow: O(n^2) because each + creates a new string
func buildSlow(n int) string {
    result := ""
    for i := 0; i < n; i++ {
        result += fmt.Sprintf("%d ", i)  // Copies entire string each time!
    }
    return result
}

// Fast: O(n) using strings.Builder
func buildFast(n int) string {
    var sb strings.Builder
    for i := 0; i < n; i++ {
        fmt.Fprintf(&sb, "%d ", i)  // Writes directly to builder
    }
    return sb.String()
}

// Alternative: using WriteString for simple appends
func buildFast2(n int) string {
    var sb strings.Builder
    for i := 0; i < n; i++ {
        if i > 0 {
            sb.WriteString(" ")
        }
        sb.WriteString(strconv.Itoa(i))
    }
    return sb.String()
}

