func isValid(s string) bool {
    stack := []rune{}

    // Map closing brackets to their opening counterparts
    pairs := map[rune]rune{
        ')': '(',
        ']': '[',
        '}': '{',
    }

    for _, char := range s {
        // If it's an opening bracket, push to stack
        if char == '(' || char == '[' || char == '{' {
            stack = append(stack, char)
        } else {
            // It's a closing bracket
            // Check if stack is empty or top doesn't match
            if len(stack) == 0 {
                return false  // No opening bracket to match
            }
            if stack[len(stack)-1] != pairs[char] {
                return false  // Wrong type of bracket
            }
            stack = stack[:len(stack)-1]  // Pop matching bracket
        }
    }

    return len(stack) == 0  // All brackets matched?
}

// isValid("()")     -> true
// isValid("()[]{}") -> true
// isValid("(]")     -> false
// isValid("([)]")   -> false

func reverseString(s string) string {
    stack := []rune{}

    // Push all characters
    for _, char := range s {
        stack = append(stack, char)
    }

    // Pop all characters (comes out reversed)
    result := []rune{}
    for len(stack) > 0 {
        result = append(result, stack[len(stack)-1])
        stack = stack[:len(stack)-1]
    }

    return string(result)
}

