import "container/heap"

func findKLargest(nums []int, k int) []int {
    h := &IntHeap{}  // Min heap
    heap.Init(h)

    for _, num := range nums {
        heap.Push(h, num)

        // If heap is too big, remove the smallest
        if h.Len() > k {
            heap.Pop(h)
        }
    }

    // The heap now contains the K largest elements
    result := make([]int, k)
    for i := k - 1; i >= 0; i-- {
        result[i] = heap.Pop(h).(int)
    }
    return result
}

