// Build adjacency list from edge list
// edges = [[0,1], [0,2], [1,2]] means: 0-1, 0-2, 1-2
func buildGraph(n int, edges [][]int) [][]int {
    graph := make([][]int, n)

    for _, edge := range edges {
        u, v := edge[0], edge[1]
        graph[u] = append(graph[u], v)
        graph[v] = append(graph[v], u)  // Remove for directed graph
    }

    return graph
}

