// Edge struct for weighted graphs
type Edge struct {
    To     int
    Weight int
}

// Build weighted adjacency list
func buildWeightedGraph(n int, edges [][]int) [][]Edge {
    // edges format: [[from, to, weight], ...]
    graph := make([][]Edge, n)

    for _, e := range edges {
        from, to, weight := e[0], e[1], e[2]
        graph[from] = append(graph[from], Edge{to, weight})
        graph[to] = append(graph[to], Edge{from, weight})  // Undirected
    }

    return graph
}

// Access: graph[0] = [{To: 1, Weight: 5}, {To: 2, Weight: 3}]

func dfs(graph [][]int, start int) []int {
    visited := make(map[int]bool)
    result := []int{}

    // Define recursive helper inside function
    var explore func(node int)
    explore = func(node int) {
        // Skip if already visited
        if visited[node] {
            return
        }

        // Mark as visited and process
        visited[node] = true
        result = append(result, node)

        // Explore all neighbors
        for _, neighbor := range graph[node] {
            explore(neighbor)
        }
    }

    explore(start)
    return result
}

// For graph: 0-[1,2], 1-[0,3], 2-[0], 3-[1]
// dfs(graph, 0) might return [0, 1, 3, 2]

func bfs(graph [][]int, start int) []int {
    visited := make(map[int]bool)
    queue := []int{start}
    visited[start] = true
    result := []int{}

    for len(queue) > 0 {
        // Dequeue front element
        node := queue[0]
        queue = queue[1:]
        result = append(result, node)

        // Add unvisited neighbors to queue
        for _, neighbor := range graph[node] {
            if !visited[neighbor] {
                visited[neighbor] = true
                queue = append(queue, neighbor)
            }
        }
    }

    return result
}

// For same graph, bfs(graph, 0) returns [0, 1, 2, 3]
// (processes by distance from start)

func shortestPath(graph [][]int, start, end int) int {
    if start == end {
        return 0
    }

    visited := make(map[int]bool)
    queue := []int{start}
    visited[start] = true
    distance := 0

    for len(queue) > 0 {
        distance++
        levelSize := len(queue)  // Nodes at current distance

        // Process all nodes at this distance
        for i := 0; i < levelSize; i++ {
            node := queue[0]
            queue = queue[1:]

            for _, neighbor := range graph[node] {
                if neighbor == end {
                    return distance  // Found shortest path!
                }
                if !visited[neighbor] {
                    visited[neighbor] = true
                    queue = append(queue, neighbor)
                }
            }
        }
    }

    return -1  // No path exists
}

// Direction arrays for 4-directional movement
var directions = [][]int{{0, 1}, {0, -1}, {1, 0}, {-1, 0}}

// Check if position is valid
func isValid(grid [][]int, r, c int) bool {
    return r >= 0 && r < len(grid) && c >= 0 && c < len(grid[0])
}

// Get all valid neighbors
func getNeighbors(grid [][]int, r, c int) [][]int {
    neighbors := [][]int{}
    for _, d := range directions {
        nr, nc := r+d[0], c+d[1]
        if isValid(grid, nr, nc) {
            neighbors = append(neighbors, []int{nr, nc})
        }
    }
    return neighbors
}

func numIslands(grid [][]byte) int {
    if len(grid) == 0 {
        return 0
    }

    rows, cols := len(grid), len(grid[0])
    count := 0

    // DFS to mark all connected land as visited
    var markIsland func(r, c int)
    markIsland = func(r, c int) {
        // Boundary check and water/visited check
        if r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != '1' {
            return
        }

        grid[r][c] = '0'  // Mark as visited (sink the land)

        // Explore all 4 directions
        markIsland(r+1, c)  // down
        markIsland(r-1, c)  // up
        markIsland(r, c+1)  // right
        markIsland(r, c-1)  // left
    }

    // Scan entire grid
    for r := 0; r < rows; r++ {
        for c := 0; c < cols; c++ {
            if grid[r][c] == '1' {
                count++           // Found new island
                markIsland(r, c)  // Mark entire island as visited
            }
        }
    }

    return count
}

