// Variadic version: min/max of multiple values
func MinOf[T cmp.Ordered](values ...T) T {
    if len(values) == 0 {
        panic("MinOf requires at least one argument")
    }
    result := values[0]
    for _, v := range values[1:] {
        if v < result {
            result = v
        }
    }
    return result
}

