// Generic Stack - works with any type
type Stack[T any] []T

// Push adds element to top
func (s *Stack[T]) Push(v T) {
    *s = append(*s, v)
}

// Pop removes and returns top element
func (s *Stack[T]) Pop() T {
    if s.IsEmpty() {
        panic("pop from empty stack")
    }
    old := *s
    n := len(old)
    v := old[n-1]
    *s = old[:n-1]
    return v
}

// Peek returns top element without removing
func (s *Stack[T]) Peek() T {
    if s.IsEmpty() {
        panic("peek on empty stack")
    }
    return (*s)[len(*s)-1]
}

// IsEmpty returns true if stack has no elements
func (s *Stack[T]) IsEmpty() bool {
    return len(*s) == 0
}

// Len returns number of elements
func (s *Stack[T]) Len() int {
    return len(*s)
}

// Contains checks if slice contains an element
func Contains[T comparable](s []T, target T) bool {
    for _, v := range s {
        if v == target {
            return true
        }
    }
    return false
}

// IndexOf returns index of element, or -1 if not found
func IndexOf[T comparable](s []T, target T) int {
    for i, v := range s {
        if v == target {
            return i
        }
    }
    return -1
}

// Reverse slice in place
func Reverse[T any](s []T) {
    for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
        s[i], s[j] = s[j], s[i]
    }
}

// Usage
nums := []int{1, 2, 3, 4, 5}
fmt.Println(Contains(nums, 3))  // true
fmt.Println(IndexOf(nums, 4))   // 3
Reverse(nums)
fmt.Println(nums)               // [5 4 3 2 1]

// Filter returns elements where f returns true
func Filter[T any](s []T, f func(T) bool) []T {
    result := make([]T, 0)
    for _, v := range s {
        if f(v) {
            result = append(result, v)
        }
    }
    return result
}

// Map transforms each element using f
func Map[T, U any](s []T, f func(T) U) []U {
    result := make([]U, len(s))
    for i, v := range s {
        result[i] = f(v)
    }
    return result
}

// Usage examples
