func maxProfit(prices []int) int {
    // 1. Edge cases first
    if len(prices) == 0 {
        return 0
    }

    // 2. Initialize variables
    minPrice := prices[0]
    maxProfit := 0

    // 3. Main logic
    for _, price := range prices {
        if price < minPrice {
            minPrice = price
        } else if price - minPrice > maxProfit {
            maxProfit = price - minPrice
        }
    }

    // 4. Return result
    return maxProfit
}

func lengthOfLIS(nums []int) int {
    // dp[i] = smallest ending element of increasing subsequence of length i+1
    // This allows binary search to find where new elements fit
    dp := []int{}

    for _, num := range nums {
        // Find insertion point using binary search
        i := sort.Search(len(dp), func(i int) bool {
            return dp[i] >= num
        })

        if i == len(dp) {
            dp = append(dp, num)  // Extend LIS
        } else {
            dp[i] = num  // Found smaller ending for this length
        }
    }

    return len(dp)  // Length of dp = length of LIS
}

